class Solution {
    public boolean judgeCircle(String moves) {
        int x = 0, y = 0;
        for (char c : moves.toCharArray()) {
            if (c == 'U') y++;
            else if (c == 'D') y--;
            else if (c == 'L') x--;
            else if (c == 'R') x++;
        }
        return x == 0 && y == 0;
    }
}

class Solution {
    public boolean judgeCircle(String moves) {
        int[] counts = new int[128];
        for (char c : moves.toCharArray()) {
            counts[c]++;
        }
        return counts['U'] == counts['D'] && counts['L'] == counts['R'];
    }
}

class Solution {
    public boolean judgeCircle(String moves) {
        if (axisBalance(moves, 'R', 'L') != 0) {
            return false;
        }
        return axisBalance(moves, 'U', 'D') == 0;
    }

    private int axisBalance(String moves, char positive, char negative) {
        int balance = 0;
        for (int i = 0; i < moves.length(); i++) {
            char move = moves.charAt(i);
            if (move == positive) {
                balance++;
            } else if (move == negative) {
                balance--;
            }
        }
        return balance;
    }
}

class Solution {
    public boolean judgeCircle(String moves) {
        int[] dx = new int[128];
        int[] dy = new int[128];
        dx['R'] = 1;
        dx['L'] = -1;
        dy['U'] = 1;
        dy['D'] = -1;

        int x = 0;
        int y = 0;
        for (int i = 0; i < moves.length(); i++) {
            char move = moves.charAt(i);
            x += dx[move];
            y += dy[move];
        }
        return x == 0 && y == 0;
    }
}

class Solution {
    public boolean judgeCircle(String moves) {
        int base = moves.length() + 1;
        int displacement = 0;
        for (int i = 0; i < moves.length(); i++) {
            char c = moves.charAt(i);
            if (c == 'R') displacement += base;
            else if (c == 'L') displacement -= base;
            else if (c == 'U') displacement++;
            else displacement--;
        }
        return displacement == 0;
    }
}
